import{H as e,V as t,et as n,j as r}from"./chunks/framework.BWKSSupd.js";var i=JSON.parse(`{"title":"Nuxt","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/essentials/nuxt.md","filePath":"en/guide/essentials/nuxt.md","lastUpdated":1786185592000}`),a={name:`en/guide/essentials/nuxt.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="nuxt" tabindex="-1">Nuxt <a class="header-anchor" href="#nuxt" aria-label="Permalink to “Nuxt”">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Nuxt is not supported yet</p><p>The current version doesn&#39;t support Nuxt. All tab configuration goes through <code>meta.routerTab</code> (see <a href="./">Getting Started</a>), and page-level dynamic info goes through <a href="./../advanced/dynamic-tab-info.html"><code>useRouterPage()</code></a>. See <a href="#ssr-limitations">SSR Limitations</a> below for why it isn&#39;t supported yet.</p></div><h2 id="ssr-limitations" tabindex="-1">SSR Limitations <a class="header-anchor" href="#ssr-limitations" aria-label="Permalink to “SSR Limitations”">​</a></h2><p>Tab caching itself conflicts with SSR:</p><ul><li>Caching relies on <code>KeepAlive</code> and client-side component instances staying alive; there&#39;s no &quot;tab history&quot; concept during server-side rendering</li><li>Tab restoration (<code>restore</code>) relies on <code>sessionStorage</code>, which isn&#39;t available on the server</li><li>Iframe tabs can only mount on the client</li></ul><p>So even if Nuxt 3 support is added in the future, it can only run as a <strong>client-only plugin</strong> (<code>ssr: false</code> or wrapped in <code>&lt;ClientOnly&gt;</code>), and this path hasn&#39;t been verified yet.</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to “Alternatives”">​</a></h2><p>For projects that need SSR, it&#39;s recommended to use tabs only in admin/back-office areas (which usually don&#39;t need SEO or first-screen SSR) and configure that area for client-side rendering.</p><p>If you get this working with Nuxt 3, feel free to share your approach on <a href="https://github.com/bhuh12/vue-router-tab/issues" target="_blank" rel="noreferrer">GitHub Issues</a>.</p>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};